  "sourceGroupForecastCoverage": "全世界。NO、SE、FI、DK では MET Norway を優先。DWD MOSMIX は DWD 領域のみ（北緯約 46.5–55.5°、東経 5–16°、ドイツ国外も含む）。",
  "sourceGroupUvCoverage": "全世界。",
